using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Collections.Generic;
class Offline70BoosterRewardsFG47 {
 internal static readonly uint[,] Pool0=new uint[,] {{2682609,32390,25},{2682609,300,50},{2682609,100,100},{2682609,80,200},{2682610,32390,25},{2682610,300,50},{2682610,100,100},{2682610,80,200},{2682611,910,25},{2682611,300,50},{2682611,100,100},{2682611,80,200},{2682612,32390,25},{2682612,300,50},{2682612,100,100},{2682612,80,200}};
 internal static readonly uint[,] Pool1=new uint[,] {{2682613,65340,1},{2682613,100,2},{2682613,80,5},{2682615,500,1},{2682615,100,2},{2682615,80,5},{2682609,10800,25},{2682609,100,50},{2682610,10800,25},{2682610,100,50},{2682611,1000,25},{2682611,100,50},{2682612,10800,25},{2682612,100,50}};
 internal static void Register(){foreach(uint id in new uint[]{2682609,2682610,2682611,2682612,2682613,2682615}){Offline70EconomyItemDefinition d=new Offline70EconomyItemDefinition{ItemId=id,Kind=1,StackLimit=1000};if(id==2682609){d.HpRecoveryPercent=30;d.CooldownMilliseconds=2000;d.CooldownGroup=5;}if(id==2682610)d.MpRecoveryPercent=30;if(id==2682611){d.HpRecoveryPercent=30;d.MpRecoveryPercent=30;d.CooldownMilliseconds=10000;d.CooldownGroup=2;}if(id==2682612){d.NativeStatusRecovery=true;d.CooldownMilliseconds=10000;d.CooldownGroup=2;}Offline70Economy.RegisterMetadata(d);}}
 // Operational stack ceiling1000, not a claim about unspecified native PVF defaults.
 internal static bool RewardItem(uint id){return id>=2682609&&id<=2682613||id==2682615;}
 internal static bool PendingUse(uint id){return false;}
 internal static uint[] Draw(int pool,uint roll){if(pool<0||pool>1||roll>=100000)throw new InvalidDataException("Booster roll bounds");uint[,] rows=pool==0?Pool0:Pool1;uint total=0;for(int i=0;i<rows.GetLength(0);i++){total+=rows[i,1];if(roll<total)return new uint[]{rows[i,0],rows[i,2]};}throw new InvalidDataException("Booster pool weights");}
 internal static uint[][] Plan(string receipt){uint[][] result=new uint[2][];for(int pool=0;pool<2;pool++){for(int attempt=0;;attempt++){byte[] h;using(SHA256 sha=SHA256.Create())h=sha.ComputeHash(Encoding.UTF8.GetBytes(receipt+":"+pool+":"+attempt));uint value=BitConverter.ToUInt32(h,0);if(value<4294900000U){result[pool]=Draw(pool,value%100000);break;}}}return result;}
 // Require room for every possible draw before opening: a full bag cannot
 // cause repeated attempts to reroll a committed result.
 static void AdmitCapacity(Offline70EconomyState s){int free=0;for(ushort slot=57;slot<89;slot++)if(Offline70Economy.Find(s,0,slot)==null)free++;Dictionary<uint,uint> spare=new Dictionary<uint,uint>();foreach(Offline70EconomyEntry e in s.Inventory)if(e.List==0&&RewardItem(e.ItemId)){uint n;spare.TryGetValue(e.ItemId,out n);spare[e.ItemId]=n+1000-e.Quantity;}for(int a=0;a<Pool0.GetLength(0);a++)for(int b=0;b<Pool1.GetLength(0);b++){uint id0=Pool0[a,0],id1=Pool1[b,0],q0=Pool0[a,2],q1=Pool1[b,2],sp0,sp1;spare.TryGetValue(id0,out sp0);spare.TryGetValue(id1,out sp1);if(id0==id1){q0+=q1;q1=0;}int need=(int)((q0>sp0?q0-sp0+999:0)/1000)+(int)((q1>sp1?q1-sp1+999:0)/1000);if(need>free)throw new InvalidDataException("Reserve space for both booster rewards");}}
 internal static Offline70EconomyState Open(string path,string receipt,ushort slot,uint[][] rewards,out bool duplicate){return Offline70Economy.Apply(path,receipt,"booster-random",slot+":2682628:"+rewards[0][0]+":"+rewards[0][1]+":"+rewards[1][0]+":"+rewards[1][1],delegate(Offline70EconomyState s){Offline70EconomyEntry e=Offline70Economy.Find(s,0,slot);if(e==null||e.ItemId!=2682628||e.Quantity!=1)throw new InvalidDataException("Missing second-stage booster");s.Inventory.Remove(e);AdmitCapacity(s);foreach(uint[] r in rewards)Offline70Economy.AddAssetItem(s,r[0],r[1]);},out duplicate);}
 internal static byte[] Reply(ushort slot,uint[][] rewards,byte[] keys){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)1);w.Write(slot);w.Write((uint)2682628);w.Write((uint)1);w.Write((ushort)2);foreach(uint[] r in rewards){w.Write(r[0]);w.Write(r[1]);}return Offline70RoleProtocol.BatchPacketFG(1,175,m.ToArray(),keys,true);}}
}
